The telemetry points to one root cause: ts-config-service's database access failed, and the error propagated up the call chain to the user-facing dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-config-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) c, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-config-service' AND span_name IN ('SELECT Config','ConfigRepository.findByName') GROUP BY ALL",
          "claim": "ts-config-service SELECT Config and ConfigRepository.findByName spans all end in Error after about 30 s (39 each)."
        },
        {
          "kind": "log",
          "sql": "SELECT level, substr(message,1,200) msg, count(*) c FROM abnormal_logs WHERE service_name='ts-config-service' AND level IN ('ERROR','SEVERE') GROUP BY ALL ORDER BY c DESC",
          "claim": "ts-config-service logs HikariPool connection timeouts, Communications link failure, and Unable to acquire JDBC connection errors."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, round(avg(value),2) v, round(max(value),2) mx FROM abnormal_metrics_sum WHERE metric IN ('db.client.connections.pending_requests','db.client.connections.timeouts','db.client.connections.usage') AND service_name='ts-config-service' GROUP BY ALL",
          "claim": "ts-config-service pool shows pending requests and timeouts with zero connections in use during the incident."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, metric, round(avg(value),2) v FROM abnormal_metrics_sum WHERE metric='k8s.pod.network.errors' AND attr_k8s_deployment_name='ts-config-service' GROUP BY ALL",
          "claim": "ts-config-service pod shows zero network errors, so the transport layer to MySQL shows no fault signal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-config-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-seat-service' AND c.service_name='ts-config-service' GROUP BY ALL",
          "claim": "All 36 calls from ts-seat-service to ts-config-service ended in Error, with the same errors reported by the seat service."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-travel-service' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "All 9 calls from ts-travel-service to ts-seat-service ended in Error after about 60 s."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-travel2-service' AND c.service_name='ts-seat-service' GROUP BY ALL",
          "claim": "All 9 calls from ts-travel2-service to ts-seat-service ended in Error after about 60 s."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Seven of 11 calls from ts-route-plan-service to ts-travel-service ended in Error."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "Three of five calls from ts-route-plan-service to ts-travel2-service ended in Error."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "All 10 calls from ts-travel-plan-service to ts-route-plan-service ended in Error."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) child_err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "All 10 calls from ts-ui-dashboard to ts-travel-plan-service ended in Error, reaching the user-facing tier."
        }
      ]
    }
  ]
}
